// Testcase Generator Script (C++17)
// Standard output will be used as the testcase input (stdin).
#include <iostream>
#include <random>
#include <vector>
using namespace std;

int main() {
    mt19937_64 rng(random_device{}());
    uniform_int_distribution<int> distN(1, 100);
    uniform_int_distribution<int> distVal(1, 1000);

    int n = distN(rng);
    cout << n << "\n";
    for (int i = 0; i < n; i++) {
        cout << distVal(rng) << (i == n - 1 ? "" : " ");
    }
    cout << "\n";
    return 0;
}
